Ltac scs_nil :=
  lazymatch goal with
  | |- scs_denot _ _ _ ?l => let l' := eval vm_compute in l in change l with l'
  | |- Forall _ ?l => let l' := eval vm_compute in l in change l with l'
  end; apply Forall_nil.

